"""[GPT-6 Astra] Preserve every sample and report the fixed experiment's limits."""
from pathlib import Path
import json
import statistics as st

out=Path(__file__).parent
records=json.loads((out/'measurements.json').read_text())
assert len(records)==168 and all(r['exit_code']==0 for r in records)
points=list(dict.fromkeys((r['case'],r['k']) for r in records))
summary=[]
for case,k in points:
    variants={}
    for variant in ['new','dc','disabled','main']:
        group={r['mode']:r for r in records if (r['case'],r['k'],r['variant'])==(case,k,variant)}
        timing=[r for r in group['timing']['rows'] if r['kind']=='sample']
        count=[r for r in group['count']['rows'] if r['kind']=='sample']
        assert len(timing)==7 and len(count)==3
        assert all(r['oracle']=='pass' for r in timing+count)
        values=[r['whole_query_ns']/1e6 for r in timing]
        metrics=['allocs','reallocs','requested_bytes','peak_live_delta']
        assert len({tuple(r[m] for m in metrics) for r in count})==1
        fixture=next(r for r in group['timing']['rows'] if r['kind']=='fixture')
        verification=next(r for r in group['verify']['rows'] if r['kind']=='verify')
        variants[variant]=dict(whole_query_ms=dict(median=st.median(values),minimum=min(values),maximum=max(values),mean=st.mean(values),sample_stddev=st.stdev(values),all_samples=values),allocations={m:count[0][m] for m in metrics},fixture=fixture,verification=verification,rss_bytes=dict(setup=fixture['setup_max_rss'],after_warmup=timing[0]['pre_query_max_rss'],final_cumulative=timing[-1]['post_query_max_rss'],increase_after_warmup=timing[-1]['post_query_max_rss']-timing[0]['pre_query_max_rss']))
    ratios={f'new_over_{v}':variants['new']['whole_query_ms']['median']/variants[v]['whole_query_ms']['median'] for v in ['dc','disabled','main']}
    ratios['disabled_over_main']=variants['disabled']['whole_query_ms']['median']/variants['main']['whole_query_ms']['median']
    disjoint={v:variants['new']['whole_query_ms']['maximum']<variants[v]['whole_query_ms']['minimum'] or variants['new']['whole_query_ms']['minimum']>variants[v]['whole_query_ms']['maximum'] for v in ['dc','disabled','main']}
    summary.append(dict(case=case,k=k,variants=variants,median_ratios=ratios,new_ranges_disjoint_from=disjoint))
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')

